node -e "
const s=require('fs').readFileSync('node_modules/next/dist/server/config-shared.d.ts','utf8');
// find top-level NextConfig interface block
const i=s.indexOf('interface NextConfig');
const seg=s.slice(i);
const m=seg.match(/^\s*cacheComponents\?:.*$/m);
console.log('NextConfig top-level cacheComponents:', m? m[0].trim() : 'NOT FOUND');
const j=s.indexOf('ExperimentalConfig');
const seg2=s.slice(j);
const m2=seg2.match(/^\s*cacheComponents\?:.*$/m);
console.log('Experimental cacheComponents:', m2? m2[0].trim():'NOT FOUND');
"

